// kill process using os specific routine
void os_kill(pproc p);

void os_kill(pproc p) {
#ifdef _WIN32
  // arbitrarily chosen exit code
  TerminateJobObject(p->job, ERROR_REQUEST_ABORTED);
#else
  kill(-p->id, SIGKILL);
#endif
}

void init_process_list () {
  processes = init_list(parallel);
}

void kill_processes(int key, char *id) {
  for (int i = 0; i < processes->len; i++) {
    pproc p = processes->data[i];
    if (p->client_key == key &&
	(id == NULL || !strcmp(p->task_id, id))) {
      os_kill(p);
    }
  }

let warning id ?loc p =
    let open Format in
    let b = Buffer.create 100 in
    let fmt = formatter_of_buffer b in
    pp_set_margin fmt 1000000000;
    pp_open_box fmt 0;
    let handle fmt =
      pp_print_flush fmt (); !warning_hook ?loc (Buffer.contents b) in
    if warning_active id then kfprintf handle fmt p else ifprintf fmt p

let get_prover_stats stat =
  Record [
    "count", Int stat.count;
    "max_steps", Int stat.max_steps;
    "max_time", StandardFloat stat.max_time
  ]

let get_stats (stats, stat_checker) =
  (* Compute the stats for goal solved by transformations as a fake prover. *)
  let fake_prover_ch =
    Whyconf.{prover_name = "Checker"; prover_version = ""; prover_altern = ""}
  in
  match stats with
  | None -> []
  | Some s ->
    if stat_checker <> 0 then
      Whyconf.Hprover.add s fake_prover_ch
        {count = stat_checker; max_steps = 0; max_time = 0.0};
    let kv_list = Whyconf.Hprover.fold (fun k v acc -> (k,v)::acc) s [] in
    let get_name pr = pr.Whyconf.prover_name in
    [ "stats",
      Record (List.map (fun (k,v) -> get_name k, get_prover_stats v) kv_list) ]

and proof_result_to_json prover r =
  let answer =
    Pp.sprintf "%a"
      Call_provers.print_prover_answer r.Call_provers.pr_answer in
  let steps =
    Gnat_config.back_convert_steps ~prover r.Call_provers.pr_steps in
  Json_base.Record [
    "time", Json_base.Float r.Call_provers.pr_time;
    "steps", Json_base.Int steps;
    "result", Json_base.String answer;
  ]

let schedule_goal ~callback c g =
   (* actually schedule the goal, ie call the prover. This function returns
      immediately. *)
  let check = get_check_of_goal g in
  let s = c.Controller_itp.controller_session in
  let warn = Gnat_expl.is_warning_kind (Gnat_expl.get_check_kind check) in
  if Gnat_config.parallel > 1 then begin
    let provers =
      if warn then [Option.get (Gnat_config.prover_warn)] else Gnat_config.provers
    in
    let remaining = ref (List.length provers) in
    let callback pa pas =
      let prover =
        (Session_itp.get_proof_attempt_node s pa).Session_itp.prover.Whyconf.prover_name
      in
      if Gnat_config.logging then Logging.log g prover pas;
      if !remaining = 0 then ()
      else match pas with
        | Controller_itp.Done pr ->
          remaining := !remaining - 1;
          begin match pr.Call_provers.pr_answer with
          | Call_provers.Valid ->
            C.interrupt_proof_attempts_for_goal c g;
            remaining := 0;
            callback pa pas
          | _ ->
            if !remaining = 0 then callback pa pas else ()
          end
        | _ -> ()
    in
    List.iter (fun p -> schedule_goal_with_prover ~callback c g p) provers
  end else begin
    let p = if warn then Option.get (Gnat_config.prover_warn)
      else find_best_untried_prover c.Controller_itp.controller_session g in
    schedule_goal_with_prover ~callback c g p
  end

